.card {
  width: 260px;
  margin: 24px;
  padding: 16px;
  border: 1px solid #d4d4d8;
  font-family: system-ui, sans-serif;
}

.card-art {
  display: block;
  width: 100%;
  height: 140px;
  object-fit: cover;
}

.card p,
.card h2,
.stats {
  margin: 0;
}

.stats {
  padding: 0;
  list-style: none;
}

/* ---- Solution ---- */
.card {
  position: relative;
  padding: 14px;
  border: 4px solid transparent;
  border-radius: 18px;
  background-image: linear-gradient(#1c1917, #1c1917), linear-gradient(160deg, #fbbf24, #f97316, #dc2626);
  background-origin: border-box;
  background-clip: padding-box, border-box;
  box-shadow: 0 10px 30px rgb(220 38 38 / 0.35);
  color: #fafaf9;
}

.ribbon {
  position: absolute;
  top: 18px;
  right: -8px;
  padding: 4px 16px 4px 22px;
  background-color: #fbbf24;
  color: #1c1917;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, 10px 50%);
}

.card-art {
  box-sizing: border-box;
  border: 2px solid #fbbf24;
  border-radius: 10px;
}

.card .card-name {
  margin-top: 12px;
  font-size: 22px;
}

.card-type {
  color: #fbbf24;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.card .stats {
  display: grid;
  gap: 8px;
  margin-top: 14px;
  padding: 10px;
  border-radius: 10px;
  background-color: rgb(255 255 255 / 0.06);
}

.stat {
  display: grid;
  grid-template-columns: 64px 1fr;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.bar {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background-color: #44403c;
}

.bar::before {
  content: "";
  display: block;
  width: var(--value);
  height: 100%;
  background-image: linear-gradient(90deg, #f97316, #fbbf24);
}

.attack {
  --value: 85%;
}

.defence {
  --value: 40%;
}

.speed {
  --value: 70%;
}

.card .flavour {
  margin-top: 12px;
  color: #a8a29e;
  font-size: 12px;
  font-style: italic;
  text-align: center;
}
